def compute(vars):
    total = vars["v1"] + vars["v2"] + vars["v3"] + vars["v4"] + vars["v5"]
    return {
        "value": total,
        "trace": {
            "total_target_amount": total,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "dollars"
            }
